import hashlib
import math

class BloomFilter:
    """A simple Bloom Filter implementation to test membership with a 
    defined false positive rate. Utilizes a bit array for space efficiency 
    and multiple hash functions for better accuracy.

    The optimal bit array size and number of hash functions are calculated
    based on the expected number of items and the desired false positive rate.
    """

    def __init__(self, expected_items: int, false_positive_rate: float) -> None:
        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate

        # Calculate optimal bit array size
        self.size = self._optimal_bit_array_size(expected_items, false_positive_rate)
        # Calculate optimal number of hash functions
        self.hash_count = self._optimal_number_of_hash_functions(self.size, expected_items)

        self.bit_array = [False] * self.size

    def _optimal_bit_array_size(self, n: int, p: float) -> int:
        """Calculate the optimal size of the bit array."""
        return math.ceil(-(n * math.log(p)) / (math.log(2) ** 2))

    def _optimal_number_of_hash_functions(self, m: int, n: int) -> int:
        """Calculate the optimal number of hash functions."""
        return max(1, int((m / n) * math.log(2)))

    def _hashes(self, item: str) -> list:
        """Create multiple hash values for the given item."""
        hashes = []
        for i in range(self.hash_count):
            hash_value = hashlib.md5((item + str(i)).encode()).hexdigest()
            hashes.append(int(hash_value, 16) % self.size)
        return hashes

    def add(self, item: str) -> None:
        """Add an item to the Bloom Filter."""
        for hash_value in self._hashes(item):
            self.bit_array[hash_value] = True

    def contains(self, item: str) -> bool:
        """Check if an item is in the Bloom Filter."""
        return all(self.bit_array[hash_value] for hash_value in self._hashes(item))

