class BloomFilter:
    """An alternative Bloom Filter implementation employing a different
    strategy for hash functions and bit manipulation while achieving 
    the same functionality. This version focuses on simple arithmetic 
    for determining hash indices and uses a native list for bit representation.
    """

    def __init__(self, expected_items: int, false_positive_rate: float) -> None:
