    def _calculate_bit_array_size(self, n: int, p: float) -> int:
        """Calculate the size of the bit array using a different formula to ensure optimal space usage."""
        return math.ceil(-n * math.log(p) / (math.log(2) ** 2))

    def _calculate_hash_count(self, m: int, n: int) -> int:
        """Calculate the number of hash functions required."""
        return max(1, math.ceil((m / n) * math.log(2)))

    def _custom_hash(self, item: str) -> int:
        """Generate a base hash value and combine it with the hash index for diversity."""
        hash1 = int(hashlib.md5(item.encode()).hexdigest(), 16)
        hash2 = int(hashlib.sha1(item.encode()).hexdigest(), 16)
        return (hash1 + hash2) % self.bit_array_size

    def _hash(self, item: str, seed: int) -> int:
        """Return a unique index for the hash function by using a seed to alter the base hash."""
        combined_hash = self._custom_hash(item) + seed
        return combined_hash % self.bit_array_size

    def add(self, item: str) -> None:
        """Add an item to the Bloom Filter."""
        for seed in range(self.hash_function_count):
            index = self._hash(item, seed)
            self.bit_array[index] = 1

    def contains(self, item: str) -> bool:
        """Check if an item is likely in the Bloom Filter."""
        for seed in range(self.hash_function_count):
            index = self._hash(item, seed)
            if self.bit_array[index] == 0:
